/**
 * Query plans the deployed model (Haiku, served as anthropic/claude-haiku-5.5) returned on 2026-10-10 for live questions on the
 * live USGS and Open-Meteo feeds and a small uploaded CSV. They are the plans the browser received, checked by the server first.
 * Used only by tests; the app itself always asks the model. Source: the d3-live capture of the fix round.
 */
export interface RecordedReply {
  dataset: 'quakes' | 'weather' | 'fruit'
  question: string
  plan: Record<string, unknown>
}

